import { Option, Schema } from "effect"
import { MARKER_LINES, MARKERS, MAX_MANIFEST_BYTES, manifestIn } from "./contract"
import { type Generated, Manifest } from "./schema"

// Whether a repository file is generated (docs/features/repo.md#generated-files): pure, so the repository view, the
// branch's editor and a TUI decide the same way. A file the repository's manifest lists is generated by that flow;
// failing that, a header marker in its first lines says so. A manifest that doesn't read marks nothing.

const decodeManifest = Schema.decodeUnknownOption(Schema.fromJsonString(Manifest))

/**
 * The manifest nearest `path` among the repository's `paths`: its own folder's, else each folder above it, up to the
 * root's. `undefined` when no folder on the way has one.
 */
export const nearestManifest = (paths: ReadonlySet<string>, path: string): string | undefined => {
  const folders = path.split("/").slice(0, -1)
  for (let depth = folders.length; depth >= 0; depth--) {
    const manifest = manifestIn(folders.slice(0, depth).join("/"))
    if (paths.has(manifest)) return manifest
  }
  return undefined
}

/** The manifest in `text`, or none when it is too large or isn't one. */
export const parseManifest = (text: string | undefined): Option.Option<Manifest> =>
  text === undefined || text.length > MAX_MANIFEST_BYTES ? Option.none() : decodeManifest(text)

/** Whether `contents` opens with a generated-file marker in its first `MARKER_LINES` lines. */
export const hasMarker = (contents: string): boolean => {
  const head = contents.split("\n", MARKER_LINES).join("\n")
  return MARKERS.some((marker) => marker.test(head))
}

/**
 * How the file at `path` is generated: listed in `manifest` (which wins, since it names the flow), or marked in its
 * own `contents`; `undefined` for a file a person writes.
 */
export const generatedOf = (
  path: string,
  contents: string | undefined,
  manifest: Option.Option<Manifest>,
): Generated | undefined => {
  if (Option.isSome(manifest) && Object.hasOwn(manifest.value.outputs, path)) {
    return { by: "manifest", output: manifest.value.outputs[path]! }
  }
  return contents !== undefined && hasMarker(contents) ? { by: "marker" } : undefined
}
